package com.bplus.share;
import android.app.*;import android.content.*;import android.net.Uri;import android.view.*;import org.json.*;import java.util.*;
public final class FileSelection {
 private final Activity a;private final String thread;private final Runnable refresh;private final Set<String> selected=new HashSet<>();private Mode mode;private android.widget.LinearLayout toolbar;private View normalHeader;private Source source;
 public interface Source{JSONArray files();}
 public FileSelection(Activity a,Source source,Runnable refresh){this(a,"",refresh);this.source=source;}
 private JSONArray data(){return source==null?Store.thread(thread):source.files();}
 private class Mode{void setTitle(String text){if(toolbar!=null)((android.widget.TextView)toolbar.getChildAt(1)).setText(text);}void finish(){if(toolbar!=null){android.view.ViewGroup parent=(android.view.ViewGroup)toolbar.getParent();if(parent!=null)parent.removeView(toolbar);}if(normalHeader!=null)normalHeader.setVisibility(View.VISIBLE);toolbar=null;mode=null;selected.clear();refresh.run();}}
 public boolean back(){if(mode==null)return false;mode.finish();return true;}
 private void begin(){android.view.ViewGroup decor=a.findViewById(android.R.id.content);if(decor.getChildCount()==0)return;android.widget.LinearLayout root=(android.widget.LinearLayout)decor.getChildAt(0);normalHeader=root.getChildAt(0);normalHeader.setVisibility(View.GONE);toolbar=Ui.row(a);toolbar.setBackgroundColor(Ui.bar);Ui.pad(toolbar,4,5,4,5,a);tool(0,a.getString(R.string.cancel),"",()->mode.finish());android.widget.TextView count=Ui.t(a,"0",18,Ui.text,App.cairoB);count.setGravity(Gravity.CENTER);toolbar.addView(count,Ui.lp(Ui.dp(a,26),Ui.dp(a,48)));tool(4,a.getString(R.string.share_other_apps),a.getString(R.string.action_share),()->action(4));tool(1,a.getString(R.string.send_files),a.getString(R.string.action_send),()->action(1));if(source==null)tool(2,a.getString(R.string.remove_message),a.getString(R.string.action_delete),()->action(2));tool(3,a.getString(R.string.select_all),a.getString(R.string.action_all),()->action(3));root.addView(toolbar,0);mode=new Mode();}
 private void tool(int icon,String description,String label,Runnable click){android.widget.LinearLayout button=Ui.col(a);button.setGravity(Gravity.CENTER);SelectionIcon glyph=new SelectionIcon(a,icon,Ui.text);button.addView(glyph,Ui.lp(Ui.dp(a,28),Ui.dp(a,28)));if(!label.isEmpty()){android.widget.TextView text=Ui.t(a,label,10,Ui.text,App.cairoSB);text.setSingleLine(true);text.setGravity(Gravity.CENTER);button.addView(text,Ui.lp(-1,Ui.dp(a,19)));}button.setContentDescription(description);button.setTooltipText(description);toolbar.addView(button,icon==0?Ui.lp(Ui.dp(a,40),Ui.dp(a,52)):Ui.lpw(1));button.setMinimumHeight(Ui.dp(a,52));button.setOnClickListener(v->click.run());}
 private void action(int id){onActionItemClicked(mode,id);}
 public View decorate(View card,JSONObject m){if(!active())return card;boolean chosen=has(m);android.widget.FrameLayout frame=new android.widget.FrameLayout(a);frame.addView(card,new android.widget.FrameLayout.LayoutParams(-2,-2));card.setOnClickListener(v->toggle(m));disableChildren(card);if(chosen){View tint=new View(a);tint.setBackground(Ui.round(0x2858a4ff,16,a));frame.addView(tint,new android.widget.FrameLayout.LayoutParams(-1,-1));tint.setOnClickListener(v->toggle(m));}View badge=new View(a){android.graphics.Paint p=new android.graphics.Paint(3);protected void onDraw(android.graphics.Canvas c){float d=getResources().getDisplayMetrics().density,cx=getWidth()/2f,cy=getHeight()/2f,r=14*d;p.setStyle(android.graphics.Paint.Style.FILL);p.setColor(Ui.bar);c.drawCircle(cx,cy,r+2*d,p);p.setColor(chosen?0xff2574d9:Ui.card);c.drawCircle(cx,cy,r,p);p.setStyle(android.graphics.Paint.Style.STROKE);p.setStrokeWidth(2.4f*d);p.setColor(android.graphics.Color.WHITE);if(chosen){android.graphics.Path check=new android.graphics.Path();check.moveTo(cx-7*d,cy);check.lineTo(cx-2*d,cy+5*d);check.lineTo(cx+8*d,cy-6*d);p.setStrokeCap(android.graphics.Paint.Cap.ROUND);p.setStrokeJoin(android.graphics.Paint.Join.ROUND);c.drawPath(check,p);}else c.drawCircle(cx,cy,r-d,p);}};android.widget.FrameLayout.LayoutParams bp=new android.widget.FrameLayout.LayoutParams(Ui.dp(a,44),Ui.dp(a,44),Gravity.TOP|Gravity.RIGHT);frame.addView(badge,bp);badge.setContentDescription(a.getString(chosen?R.string.deselect_file:R.string.select_file));badge.setOnClickListener(v->toggle(m));return frame;}
 public FileSelection(Activity a,String thread,Runnable refresh){this.a=a;this.thread=thread;this.refresh=refresh;}
 static String key(JSONObject m){return m.optString("id",m.optString("uri")+"|"+m.optString("name")+"|"+m.optLong("ts"));}
 private void disableChildren(View v){if(v instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)v;for(int i=0;i<g.getChildCount();i++){View child=g.getChildAt(i);child.setClickable(false);disableChildren(child);}}}
 public boolean active(){return mode!=null;}public boolean has(JSONObject m){return selected.contains(key(m));}
 public void toggle(JSONObject m){if(mode==null)begin();String k=key(m);if(!selected.add(k))selected.remove(k);if(selected.isEmpty()&&mode!=null)mode.finish();else if(mode!=null)mode.setTitle(String.valueOf(selected.size()));refresh.run();}
 private ArrayList<JSONObject> chosen(){ArrayList<JSONObject> out=new ArrayList<>();JSONArray t=data();for(int i=0;i<t.length();i++){JSONObject m=t.optJSONObject(i);if(m!=null&&m.optString("kind").equals("file")&&selected.contains(key(m)))out.add(m);}return out;}
 public boolean onActionItemClicked(Mode m,int id){if(id==3){JSONArray t=data();for(int i=0;i<t.length();i++){JSONObject file=t.optJSONObject(i);if(file!=null&&file.optString("kind").equals("file"))selected.add(key(file));}m.setTitle(String.valueOf(selected.size()));refresh.run();return true;}ArrayList<JSONObject> files=chosen();if(id==4){FileCards.shareMany(a,files);return true;}if(id==1){JSONArray peers=Store.peers();String[] names=new String[peers.length()];for(int i=0;i<names.length;i++)names[i]=peers.optJSONObject(i).optString("name");new AlertDialog.Builder(a).setTitle(R.string.send_files).setItems(names,(d,n)->new AlertDialog.Builder(a).setMessage(a.getString(R.string.send_selected_confirm,files.size(),names[n])).setNegativeButton(R.string.cancel,null).setPositiveButton(R.string.send_now,(confirm,k)->{JSONObject peer=peers.optJSONObject(n);new Thread(()->{int ok=0;for(JSONObject f:files)if(FileCards.available(a,f)&&TransferService.sendToPeer(peer,FileCards.uri(f),f.optString("name"),f.optLong("size")))ok++;final int sent=ok;a.runOnUiThread(()->android.widget.Toast.makeText(a,a.getString(R.string.forward_result,sent,files.size()),1).show());}).start();m.finish();}).show()).show();return true;}
 if(id==2){new AlertDialog.Builder(a).setTitle(R.string.remove_message).setItems(new String[]{a.getString(R.string.remove_cards_only),a.getString(R.string.delete_local_files)},(d,n)->new AlertDialog.Builder(a).setMessage(a.getString(n==0?R.string.remove_cards_note:R.string.delete_files_note,files.size())).setNegativeButton(R.string.cancel,null).setPositiveButton(R.string.remove_message,(c,k)->{if(n==0){synchronized(Store.class){JSONArray old=Store.thread(thread),keep=new JSONArray();for(int i=0;i<old.length();i++){JSONObject f=old.optJSONObject(i);if(f!=null&&!selected.contains(key(f)))keep.put(f);}Store.saveThread(thread,keep);}}else{int failed=0;Set<String> done=new HashSet<>();for(JSONObject f:files){Uri u=FileCards.uri(f);if(u==null){failed++;continue;}if(!done.add(u.toString()))continue;try{if(!"content".equals(u.getScheme())||a.getContentResolver().delete(u,null,null)==0)failed++;}catch(Exception e){failed++;}}android.widget.Toast.makeText(a,a.getString(R.string.delete_result,failed),1).show();}m.finish();refresh.run();}).show()).show();return true;}return false;}
}
